// Filter out unsafe topics and select 1 candidate.
// Medical assertion guard: block 발암/의료사고/효능 단정.
const BLOCKED = [
  '발암', '의료사고', '병원성', '식약처 회수', '리콜',
  'cancer', 'medical accident', 'side effect death'
];
const keyword = $('Webhook').first().json.keyword || '';
for (const w of BLOCKED) {
  if (keyword.includes(w)) {
    throw new Error(`Blocked keyword detected: ${w}`);
  }
}
const items = ($json.items || []).filter((it) => {
  const blob = `${it.title || ''} ${it.description || ''}`;
  return !BLOCKED.some((w) => blob.includes(w));
});
if (items.length === 0) {
  return [{ json: { keyword, topic: keyword, source: null, fallback: true } }];
}
const pick = items[0];
return [{
  json: {
    keyword,
    topic: keyword,
    source: { title: pick.title, link: pick.link, description: pick.description },
    fallback: false
  }
}];

